// 상관분석 및 트렌드 분석 통합 수행
const data = $input.all()[0].json;
const sensorData = data.sensor_data;
const qualityData = data.quality_data;

console.log('고급 분석 시작');

// 데이터 유효성 검사
if (!sensorData || !Array.isArray(sensorData) || sensorData.length === 0) {
  throw new Error('센서 데이터가 없습니다.');
}

// 수치 변환 함수
function toNumber(value) {
  const num = parseFloat(value);
  return isNaN(num) ? 0 : num;
}

// 피어슨 상관계수 계산
function calculatePearsonCorrelation(x, y) {
  const n = x.length;
  if (n !== y.length || n < 3) return { r: 0, p_value: 1, significance: 'none' };

  const sumX = x.reduce((a, b) => a + b, 0);
  const sumY = y.reduce((a, b) => a + b, 0);
  const sumXY = x.reduce((acc, xi, i) => acc + xi * y[i], 0);
  const sumX2 = x.reduce((acc, xi) => acc + xi * xi, 0);
  const sumY2 = y.reduce((acc, yi) => acc + yi * yi, 0);

  const numerator = n * sumXY - sumX * sumY;
  const denominator = Math.sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY));

  if (denominator === 0) return { r: 0, p_value: 1, significance: 'none' };

  const r = numerator / denominator;
  const t = r * Math.sqrt((n - 2) / (1 - r * r));

  let p_value;
  if (Math.abs(t) > 3.18) p_value = 0.001;
  else if (Math.abs(t) > 2.78) p_value = 0.01;
  else if (Math.abs(t) > 2.06) p_value = 0.05;
  else p_value = 0.1;

  let significance = 'none';
  if (p_value <= 0.001) significance = 'very_high';
  else if (p_value <= 0.01) significance = 'high';
  else if (p_value <= 0.05) significance = 'moderate';

  return { r: Math.round(r * 100) / 100, p_value: p_value, significance: significance };
}

// 트렌드 분석 함수
function analyzeTimeTrend(values, baseline) {
  if (values.length < 2) return { slope: 0, direction: 'stable', anomaly_points: 0 };

  const n = values.length;
  const x = Array.from({length: n}, (_, i) => i);
  const y = values;

  const sumX = x.reduce((a, b) => a + b, 0);
  const sumY = y.reduce((a, b) => a + b, 0);
  const sumXY = x.reduce((acc, xi, i) => acc + xi * y[i], 0);
  const sumX2 = x.reduce((acc, xi) => acc + xi * xi, 0);

  const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);

  let direction = 'stable';
  const slopeThreshold = baseline ? Math.abs(baseline.slope) * 2 : 0.1;

  if (Math.abs(slope) > slopeThreshold) {
    direction = slope > 0 ? 'increasing' : 'decreasing';
  } else if (Math.abs(slope) > slopeThreshold * 0.5) {
    direction = slope > 0 ? 'slightly_increasing' : 'slightly_decreasing';
  }

  // 이상치 감지 (간단한 IQR 방법)
  const sorted = [...values].sort((a, b) => a - b);
  const q1 = sorted[Math.floor(n * 0.25)];
  const q3 = sorted[Math.floor(n * 0.75)];
  const iqr = q3 - q1;
  const lowerBound = q1 - 1.5 * iqr;
  const upperBound = q3 + 1.5 * iqr;
  const anomalyPoints = values.filter(val => val < lowerBound || val > upperBound).length;

  return {
    slope: Math.round(slope * 1000) / 1000,
    direction: direction,
    anomaly_points: anomalyPoints
  };
}

// 목표 변수 (수분 측정값)
const moistureValue = qualityData ? toNumber(qualityData['moisture_measured_wt%']) : toNumber(data.lot_info['moisture_measured_wt%']);
const moistureThreshold = qualityData ? toNumber(qualityData['moisture_threshold_wt%']) : toNumber(data.lot_info['moisture_threshold_wt%']);
const moistureArray = new Array(sensorData.length).fill(moistureValue);

// 변수별 상관관계 및 트렌드 분석
const variables = ['exit_humidity_%', 'inlet_humidity_%', 'drying_temp_°C', 'residence_time_s'];
const correlationResults = {};
const processTrendAnalysis = [];

variables.forEach(varName => {
  const values = sensorData.map(s => toNumber(s[varName]));
  const baseline = data.historical_baseline[varName];

  // 상관관계 분석
  const correlation = calculatePearsonCorrelation(values, moistureArray);
  correlationResults[varName] = {
    pearson_r: correlation.r,
    p_value: correlation.p_value
  };

  // 트렌드 분석
  const trend = analyzeTimeTrend(values, baseline);
  const slopeChange = baseline && baseline.slope !== 0 ? Math.round(((trend.slope - baseline.slope) / Math.abs(baseline.slope)) * 100) : 0;
  const isAnomalous = Math.abs(slopeChange) > 100 || trend.anomaly_points > 1;

  let description = '기존 패턴 범위 내에서 정상적인 변화입니다.';
  if (Math.abs(slopeChange) > 200) {
    description = `평소 대비 변화율이 ${Math.abs(slopeChange)}% ${slopeChange > 0 ? '증가' : '감소'}하여 이상 징후가 감지됩니다.`;
  } else if (trend.anomaly_points > 1) {
    description = `이상치가 ${trend.anomaly_points}개 감지되었습니다.`;
  }

  processTrendAnalysis.push({
    variable: varName,
    slope: trend.slope,
    trend_direction: trend.direction,
    anomaly_points: trend.anomaly_points,
    chart_url: `https://charts.company.com/${varName.replace('%', '').replace(/[°]/g, '').replace(/[^a-zA-Z0-9_]/g, '_')}_trend.png`,
    historical_pattern_comparison: {
      baseline_slope: baseline?.slope || 0,
      baseline_anomaly_rate: baseline?.anomaly_rate || 0,
      current_vs_historical: `slope ${slopeChange > 0 ? '↑' : '↓'} ${Math.abs(slopeChange)}%, anomaly ↑ ${trend.anomaly_points}개`,
      is_anomalous: isAnomalous,
      description: description
    }
  });
});

// 이상 징후 플래그 생성
const anomalyFlags = [];
Object.entries(correlationResults).forEach(([varName, corr]) => {
  if (Math.abs(corr.pearson_r) > 0.7) {
    anomalyFlags.push(`${varName}_strong_correlation`);
  }
});

processTrendAnalysis.forEach(trend => {
  if (trend.historical_pattern_comparison.is_anomalous) {
    if (trend.variable === 'exit_humidity_%' && trend.slope > 0.1) {
      anomalyFlags.push('exit_humidity_spike');
    }
    if (trend.variable === 'residence_time_s' && trend.anomaly_points > 0) {
      anomalyFlags.push('res_time_variance_high');
    }
  }
});

// 심각도 결정
const moistureExcess = moistureValue - moistureThreshold;
let severity = 'low';
let severityScore = 0;

if (moistureExcess > 0.15) severityScore += 3;
else if (moistureExcess > 0.1) severityScore += 2;
else if (moistureExcess > 0.05) severityScore += 1;

severityScore += Object.values(correlationResults).filter(c => c.p_value <= 0.05).length * 0.5;
severityScore += processTrendAnalysis.filter(t => t.historical_pattern_comparison.is_anomalous).length * 0.7;

if (severityScore >= 4) severity = 'high';
else if (severityScore >= 2) severity = 'medium';

const result = {
  ...data,
  correlation_results: correlationResults,
  process_trend_analysis: processTrendAnalysis,
  anomaly_flags: anomalyFlags,
  severity: severity,
  severity_score: Math.round(severityScore * 10) / 10,
  analysis_timestamp: new Date().toISOString()
};

console.log('고급 분석 완료. 심각도:', severity, ', 이상 플래그:', anomalyFlags.length, '개');
return [{ json: result }];

// 최종 NG Context JSON 생성
const data = $input.all()[0].json;

console.log('최종 Context JSON 생성 시작');

